import Link from 'next/link';
import { ArrowUpRight } from 'lucide-react';
import { notFound } from 'next/navigation';
import { loadPlanningPage } from '@/lib/workspace-page';
import { financeSnapshot } from '@/lib/finance-read';
import { financeTotals,itemFigures } from '@/lib/budget';
import { formatMinor } from '@/lib/money';
import { PageHeader } from '@/components/admin/planning-ui';
import { FinanceDialog,FinanceLive,ExpenseLinkFields } from '@/components/admin/finance/finance-dialog';
import { VendorFields,ExpenseFields } from '@/components/admin/finance/fields';
import { PaymentButton,PaymentHistory } from '@/components/admin/finance/records';
import { VendorContracts,UploadContractLauncher } from '@/components/admin/vendor-contracts';
export const dynamic='force-dynamic';
const statuses:Record<string,string>={considering:'Considering',quoted:'Quote received',booked:'Booked',declined:'Not going ahead'};
export default async function VendorDetails({params}:{params:Promise<{vendorId:string}>}){
 const {wedding}=await loadPlanningPage();if(!wedding)notFound();
 const data=await financeSnapshot(wedding.id);const {vendorId}=await params;const vendor=data.vendors.find(v=>v.id===vendorId&&!v.deletedAt);if(!vendor)notFound();
 const items=data.items.filter(i=>i.vendorId===vendor.id);const totals=financeTotals(items,data.headcounts);const hasAgreed=items.some(i=>i.agreedMinor!==null);const remaining=totals.expectedMinor-totals.paidMinor;const costLabel=!items.length||items.every(i=>i.agreedMinor!==null)?'Agreed cost':items.every(i=>i.agreedMinor===null)?'Estimated cost':'Expected cost';
 const options={currency:wedding.currency,vendors:data.vendors.filter(v=>!v.deletedAt),events:data.events.filter(e=>!e.deletedAt)};
 const unlinked=data.items.filter(i=>!i.vendorId);
 const pendingExpense=items.length===1&&items[0].agreedMinor===null?items[0]:null;
 return <main className="app-shell finance-shell"><FinanceLive weddingId={wedding.id}/><PageHeader title={vendor.name} meta={`${vendor.category} · ${statuses[vendor.status]??vendor.status}`} back={{href:'/admin/vendors',label:'Vendors'}} actions={<><FinanceDialog label="Edit details" title="Edit vendor details" operation="vendor.save" weddingId={wedding.id} initial={{id:vendor.id,version:vendor.version}}><VendorFields vendor={vendor} currency={wedding.currency}/></FinanceDialog><UploadContractLauncher vendorId={vendor.id}/>{items.length===1?<PaymentButton weddingId={wedding.id} item={items[0]} currency={wedding.currency}/>:items.length>1?<a href="#expenses" className="btn-primary">Record payment</a>:null}</>}/>
  <dl className="finance-cost-strip"><div><dt>{costLabel}</dt><dd>{items.length?formatMinor(totals.expectedMinor,wedding.currency):'Not agreed'}</dd></div><div><dt>Paid</dt><dd>{formatMinor(totals.paidMinor,wedding.currency)}</dd></div><div><dt>{remaining<0?'Overpaid':'Remaining'}</dt><dd className={remaining<0?'text-[var(--danger)]':''}>{items.length?formatMinor(Math.abs(remaining),wedding.currency):'—'}</dd></div></dl>
  {items.some(i=>i.agreedMinor===null)?<p className="mt-3 text-xs text-[var(--muted-text)]">Includes estimates. {formatMinor(totals.agreedMinor,wedding.currency)} has been agreed.</p>:null}
  {vendor.status==='booked'&&!hasAgreed?<p className="notice-info mt-5">Booked. {items.length?'Review the linked expense to confirm its agreed cost.':'Confirm the agreed cost below, or link an existing expense.'} Your quote has not been committed to the budget.</p>:null}
  <div className="finance-detail-grid"><div className="min-w-0 space-y-9"><section id="expenses" className="scroll-mt-6" aria-labelledby="vendor-expenses"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><h2 id="vendor-expenses" className="section-heading">{items.length===1?'Expense':'Expenses'}</h2><FinanceDialog label={pendingExpense||!items.length?'Confirm cost':'Add another expense'} title={pendingExpense||!items.length?'Confirm vendor cost':'Add expense'} operation="expense.save" weddingId={wedding.id} initial={pendingExpense?{id:pendingExpense.id,version:pendingExpense.version,confirmCost:true}:{confirmCost:!items.length}} submitLabel="Save expense"><ExpenseFields {...options} item={pendingExpense??undefined} vendorId={vendor.id} label={vendor.category} confirmCost={Boolean(pendingExpense)||!items.length}/></FinanceDialog></div>
   {items.length?<div className="divide-y divide-[var(--border-soft)]">{items.map(item=><div key={item.id} className="flex flex-wrap items-center justify-between gap-3 border-t border-[var(--border-soft)] py-4"><div className="min-w-0"><Link href={`/admin/budget/${item.id}`} className="finance-record-link">{item.label}<ArrowUpRight className="h-3.5 w-3.5" aria-hidden/></Link><p className="mt-1 text-sm text-[var(--muted-text)]">{item.event?.title??'Whole wedding'} · {item.agreedMinor===null?'Estimate':'Agreed cost'} {formatMinor(itemFigures(item,data.headcounts).plannedMinor,wedding.currency)}</p>{data.legacyQuoteCosts.has(item.id)?<p className="mt-1 text-xs text-[var(--warning)]">Legacy quote-linked cost — review the agreement.</p>:null}{data.duplicates.has(item.id)?<p className="mt-1 text-xs text-[var(--warning)]">Similar expense — review in Budget.</p>:null}</div>{items.length>1?<PaymentButton weddingId={wedding.id} item={item} currency={wedding.currency}/>:<Link href={`/admin/budget/${item.id}`} className="btn-ghost btn-sm">Open expense</Link>}</div>)}</div>:<p className="py-3 text-sm text-[var(--muted-text)]">No expense linked yet. Confirm the cost when you’re ready; adding this vendor alone changes no totals.</p>}
   {unlinked.length?<div className="mt-3"><FinanceDialog label="Link an existing expense" title="Link existing expense" operation="expense.link" weddingId={wedding.id} initial={{vendorId:vendor.id}} submitLabel="Link expense" className="text-link text-sm"><ExpenseLinkFields expenses={unlinked.map(i=>({id:i.id,label:i.label,version:i.version}))}/></FinanceDialog></div>:null}
  </section><section aria-labelledby="vendor-payments"><h2 id="vendor-payments" className="section-heading">Payment history</h2><PaymentHistory items={items} weddingId={wedding.id} currency={wedding.currency}/></section><VendorContracts vendorId={vendor.id} contracts={vendor.contracts.map(c=>({...c,createdAt:c.createdAt.toISOString()}))}/></div>
  <aside className="finance-secondary"><h2 className="section-heading">Vendor details</h2>{vendor.quoteMinor!==null?<div className="mt-5"><p className="text-sm text-[var(--muted-text)]">Latest quote</p><p className="mt-1 font-semibold tabular-nums">{formatMinor(vendor.quoteMinor,wedding.currency)}</p><p className="mt-1 text-xs leading-relaxed text-[var(--muted-text)]">Quotes are separate from agreed costs.</p></div>:null}<div className="mt-5 space-y-2 break-words text-sm">{vendor.contactName?<p>{vendor.contactName}</p>:null}{vendor.phone?<a className="text-link block" href={`tel:${vendor.phone}`}>{vendor.phone}</a>:null}{vendor.email?<a className="text-link block" href={`mailto:${vendor.email}`}>{vendor.email}</a>:null}{vendor.website?<a className="text-link block" href={vendor.website} target="_blank" rel="noopener noreferrer">Website</a>:null}{!vendor.phone&&!vendor.email&&!vendor.contactName?<p className="text-[var(--muted-text)]">No contact details added.</p>:null}</div>{vendor.notes?<div className="mt-6"><h3 className="text-sm font-medium">Notes</h3><p className="mt-2 whitespace-pre-wrap break-words text-sm leading-relaxed text-[var(--muted-text)]">{vendor.notes}</p></div>:null}</aside></div>
 </main>;
}
